# PUT /api/sheets/{sheetId}/people/{personId}/hold — add a hold to a person. Body
# {"from":"yyyy-mm-dd","to":"yyyy-mm-dd"}; a blank from-date is the sheet's today, a blank to-date has no
# end (a hold ends on its to-date). Their OPEN claims dated within a hold and not bound by a statement
# count in no live total. A date that is not real, or a to-date before the from-date, is refused with 400
# and nothing is stored; 404 for a person not on the sheet.
viewer:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: validate
  govern: [ transaction ]
validate:
  class: net.officefloor.hq.app.person.ValidateHold
  next: snapshot
  govern: [ transaction ]
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  next: load
  govern: [ transaction ]
load:
  class: net.officefloor.hq.app.person.LoadPerson
  next: hold
  govern: [ transaction ]
hold:
  class: net.officefloor.hq.app.person.HoldPerson
  next: audit
  govern: [ transaction ]
audit:
  class: net.officefloor.hq.app.person.AuditPersonHeld
  next: rollup
  govern: [ transaction ]
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  next: respond
  govern: [ transaction ]
respond:
  class: net.officefloor.hq.app.person.RespondWithEditedPerson
  govern: [ transaction ]
# PUT /api/sheets/{sheetId}/claims/{claimId}/status/{status} — move a claim to OPEN, SETTLED or VOID.
# DRAFT -> OPEN -> SETTLED, and DRAFT, OPEN or PENDING -> VOID. A clerk settling a claim above the clerk limit
# makes it PENDING; from PENDING a steward (not its opener) approves it (SETTLED) or rejects it (OPEN, with a
# "reason" in the body). Any other change is refused with 409 and nothing is stored. 404 for a claim not on the
# sheet; 422 for a claim dated inside a closed period, or for a settle or approve of a claim with no proof whose due is
# above the proof threshold in force on its date.
viewer:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: snapshot
  govern: [ transaction ]
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  next: load
  govern: [ transaction ]
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  next: closed
  govern: [ transaction ]
closed:
  class: net.officefloor.hq.app.claim.RefuseClosedClaim
  next: apply
  govern: [ transaction ]
apply:
  class: net.officefloor.hq.app.claim.ApplyClaimStatus
  next: audit
  govern: [ transaction ]
audit:
  class: net.officefloor.hq.app.claim.AuditClaimStatus
  next: rollup
  govern: [ transaction ]
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  next: respond
  govern: [ transaction ]
respond:
  class: net.officefloor.hq.app.claim.RespondWithEditedClaim
  govern: [ transaction ]
# PUT /api/sheets/{sheetId}/claims/{claimId}/resettle — a steward re-freezes a SETTLED claim at the figure it would
# have today as an open claim bound by no statement. Refused with 422 for anyone else or any other status, and for a
# claim dated inside a closed period; nothing is stored. 404 for a claim not on the sheet.
viewer:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: snapshot
  govern: [ transaction ]
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  next: load
  govern: [ transaction ]
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  next: closed
  govern: [ transaction ]
closed:
  class: net.officefloor.hq.app.claim.RefuseClosedClaim
  next: apply
  govern: [ transaction ]
apply:
  class: net.officefloor.hq.app.claim.ApplyResettle
  next: audit
  govern: [ transaction ]
audit:
  class: net.officefloor.hq.app.claim.AuditClaimResettled
  next: rollup
  govern: [ transaction ]
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  next: respond
  govern: [ transaction ]
respond:
  class: net.officefloor.hq.app.claim.RespondWithEditedClaim
  govern: [ transaction ]
# GET /api/sheets/{sheetId}/people — the sheet's people, in the order they were added.
respond:
  class: net.officefloor.hq.app.person.RespondWithPeople
  govern: [ readonly-transaction ]
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class HoldPerson {
    // Adds a hold to the person's holds (a blank from-date is the sheet's today); a hold ends on its to-date.
    // Person is a record, so the held person is published as the response in place of the loaded one.
    public void hold(@Val HoldDates dates, @Val Person person, People people, Sheets sheets,
            Out<PersonResponse> responseOut) throws InvalidPersonException {
        LocalDate today = sheets.today(person.sheetId());
        Hold hold = new Hold(dates.from() != null ? dates.from() : today, dates.to());
        if (hold.to() != null && hold.to().isBefore(hold.from())) {
            throw new InvalidPersonException("The to-date is before the from-date.");
        }
        people.hold(person.id(), hold);
        List<Hold> holds = new ArrayList<>(person.holds());
        holds.add(hold);
        holds.sort(Comparator.comparing(Hold::from));
        Person held = new Person(person.id(), person.sheetId(), person.name(), person.grade(), person.version(),
                person.retiredFrom(), List.copyOf(holds), person.dated());
        responseOut.set(PersonResponse.from(held, today));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class AuditPersonHeld {
    public void audit(@Val HoldDates dates, @Val Person loaded, ServerHttpConnection connection, Sheets sheets,
            Audit audit) {
        audit.record(Audit.line("PERSON_HELD", loaded.sheetId(), Audit.user(connection), "name=" + loaded.name(),
                "from=" + (dates.from() != null ? dates.from() : sheets.today(loaded.sheetId()))));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPerson {
    public void respond(@Val Person person, Sheets sheets, ObjectResponse<PersonResponse> response) {
        response.send(PersonResponse.from(person, sheets.today(person.sheetId())));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class RespondWithPeople {
    public void respond(@PathVariable("sheetId") String sheetId, People people, Sheets sheets,
            ObjectResponse<List<PersonResponse>> response) {
        LocalDate today = sheets.today(sheetId.trim());
        response.send(people.list(sheetId.trim()).stream().map(p -> PersonResponse.from(p, today)).toList());
    }
}
package net.officefloor.hq.app.claim;

import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class AuditClaimStatus {
    public void audit(@Val Claim loaded, @Val ClaimResponse changed, @Val ClaimStatusRequest request, People people,
            ServerHttpConnection connection, Audit audit) {
        Person person = people.find(loaded.sheetId(), loaded.personId());
        List<String> fields = new ArrayList<>(List.of("person=" + (person == null ? "" : person.name()),
                "amount=" + changed.amount(), "date=" + changed.date()));
        // A voided claim's line carries the number it had.
        String number = changed.number() != null ? changed.number() : loaded.number();
        if (number != null) {
            fields.add("number=" + number);
        }
        ClaimStatus status = ClaimStatus.valueOf(changed.status());
        // A settled (or approved) claim's line carries the due it was fixed at.
        if (status == ClaimStatus.SETTLED) {
