// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A write refused because the record was saved by someone else since it was loaded (409). */
export class ConflictError extends Error {}

/** A write refused by a rule the screen cannot see in full (422), e.g. a claim dated in a closed period; the message is the server's. */
export class RefusedError extends Error {}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (res.status === 409) {
    throw new ConflictError(`${init?.method ?? 'GET'} ${path} -> 409`);
  }
  if (res.status === 422) {
    throw new RefusedError(await res.text());
  }
  if (!res.ok) {
    throw new Error(`${init?.method ?? 'GET'} ${path} -> ${res.status}`);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

// A write names the signed-in user (X-User) so the server can record who made the change.
function jsonHeaders(user?: string): HeadersInit {
  return user ? { 'Content-Type': 'application/json', 'X-User': user } : { 'Content-Type': 'application/json' };
}

export function postJson<T>(path: string, body: unknown, user?: string): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: jsonHeaders(user),
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown, user?: string): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: jsonHeaders(user),
    body: JSON.stringify(body),
  });
}
import { defineSlot } from '../Slot';

/**
 * The people table, column by column. A feature that shows something per person contributes
 * `Header` (a <th>, rendered in the table head) and `Cell` (a <td>, rendered in each person's row).
 */
export const PersonHeaders = defineSlot<{ sheetId: string }>('person.headers');
export const PersonCells = defineSlot<{ sheetId: string; personId: number }>('person.cells');
import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { usePersonError } from './usePersonError';
import { useUser } from '../session/useUser';
import { peopleKey, peopleQuery } from './peopleQuery';
import type { Person } from './peopleQuery';

const DATE = /^\d{4}-\d{2}-\d{2}$/;

/**
 * Whether the person has any hold, their holds, and the control that adds one from a from-date (blank: the
 * sheet's today) to an optional to-date. Their OPEN claims dated within a hold, unless bound by a statement,
 * count in no live total; a hold ends on its to-date.
 */
function PersonHold({ sheetId, personId }: { sheetId: string; personId: number }) {
  const queryClient = useQueryClient();
  const [user] = useUser();
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [error, setError] = usePersonError(personId);
  const once = useSubmitOnce();
  const person = (useQuery(peopleQuery(sheetId)).data ?? []).find((p) => p.id === personId);
  const hold = useMutation({
    mutationFn: (body: { from: string; to: string }) =>
      putJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/hold`, body, user),
    onSuccess: async () => {
      setFrom('');
      setTo('');
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
    },
    onError: () => setError('The hold could not be added.'),
  });

  return (
    <td>
      <span data-testid="person-hold">{person?.held ? 'yes' : 'no'}</span>{' '}
      {(person?.holds ?? []).map((h, i) => (
        <span key={i} data-testid="person-hold-line">
          {h.from} to {h.to ?? '…'}{' '}
        </span>
      ))}
      <input
        data-testid="person-hold-from"
        placeholder="from yyyy-mm-dd"
        value={from}
        onChange={(e) => {
          setFrom(e.target.value);
          setError('');
        }}
      />{' '}
      <input
        data-testid="person-hold-to"
        placeholder="to yyyy-mm-dd"
        value={to}
        onChange={(e) => {
          setTo(e.target.value);
          setError('');
        }}
      />{' '}
      <button
        type="button"
        data-testid="person-hold-toggle"
        disabled={hold.isPending}
        onClick={() => {
          setError('');
          const f = from.trim();
          const t = to.trim();
          if ((f !== '' && !DATE.test(f)) || (t !== '' && !DATE.test(t))) {
            setError('The dates must be yyyy-mm-dd.');
            return;
          }
          if (f !== '' && t !== '' && t < f) {
            setError('The to-date is before the from-date.');
            return;
          }
          once(() => hold.mutateAsync({ from: f, to: t }));
        }}
      >
        Hold
      </button>
      {error && <span data-testid="person-error">{error}</span>}
    </td>
  );
}

export const contributions = [
  PersonHeaders.fill({ order: 19, Component: () => <th>Hold</th> }),
  PersonCells.fill({ order: 19, Component: PersonHold }),
];
import { useSyncExternalStore } from 'react';

// One refusal per person row, shared by every cell that acts on the person (statement, retire, hold), so
// the row shows a single `person-error` and the next action on the row, whichever cell takes it, clears the last one.
const errors = new Map<number, string>();
const listeners = new Set<() => void>();

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

function setError(personId: number, error: string) {
  if ((errors.get(personId) ?? '') === error) return;
  if (error) errors.set(personId, error);
  else errors.delete(personId);
  listeners.forEach((l) => l());
}

/** The person's refusal ('' when none) and its setter. */
export function usePersonError(personId: number): [string, (error: string) => void] {
  const error = useSyncExternalStore(subscribe, () => errors.get(personId) ?? '');
  return [error, (next) => setError(personId, next)];
}
import { getJson } from '../../api/http';
import { sheetKey } from '../sheet/sheetQuery';

export type Grade = 'A' | 'B' | 'C';
export const GRADES: Grade[] = ['A', 'B', 'C'];

/**
 * `version` is raised on every edit; an edit names the version it loaded. `retiredFrom` (yyyy-mm-dd) is
 * set once the person is retired, which they are at once, whatever the date; null otherwise. `held` is whether
 * they have any hold; `holds` are their holds by from-date: their OPEN claims dated within one, unless bound by a
 * statement, count in no live total.
 */
export type Person = { id: number; name: string; grade: Grade; grades: Graded[]; version: number; retiredFrom: string | null; held: boolean; holds: Held[] };

/** A hold from `from` to `to` inclusive (yyyy-mm-dd); `to` is null when it has no end. */
export type Held = { from: string; to: string | null };

/** Whether the date (yyyy-mm-dd) falls within any of the person's holds. */
export function heldOn(person: Person | undefined, date: string): boolean {
  return (person?.holds ?? []).some((h) => h.from <= date && (h.to === null || date <= h.to));
}

/** A grade a person was given from `from` (yyyy-mm-dd) on; null for the first, from the beginning of time. */
export type Graded = { from: string | null; grade: Grade };

/** The person's grade in force on the date (yyyy-mm-dd): the one with the latest from-date on or before it. */
export function gradeOn(person: Person | undefined, date: string): Grade | undefined {
  if (!person) return undefined;
  // No from-date sorts as '', before every date.
  const applying = person.grades.filter((g) => (g.from ?? '') <= date);
  return applying.reduce<Graded | undefined>((best, g) => (!best || (g.from ?? '') > (best.from ?? '') ? g : best), undefined)
    ?.grade ?? person.grade;
}

/** Under the sheet's key, so re-loading the sheet re-reads its people. */
export const peopleKey = (sheetId: string) => [...sheetKey(sheetId), 'people'] as const;

export const peopleQuery = (sheetId: string) => ({
  queryKey: peopleKey(sheetId),
  queryFn: () => getJson<Person[]>(`/api/sheets/${encodeURIComponent(sheetId)}/people`),
});
import { getJson } from '../../api/http';
import { sheetKey } from '../sheet/sheetQuery';

/** One link: the person (`personId`) names another person on the sheet (`patronId`) as their patron. */
export type PatronLink = { personId: number; patronId: number };

/** Under the sheet's key, so re-loading the sheet re-reads its patrons. */
export const patronsKey = (sheetId: string) => [...sheetKey(sheetId), 'patrons'] as const;

export const patronsQuery = (sheetId: string) => ({
  queryKey: patronsKey(sheetId),
  queryFn: () => getJson<PatronLink[]>(`/api/sheets/${encodeURIComponent(sheetId)}/patrons`),
});

/** The ids of the person's patrons. */
export const patronIdsOf = (links: PatronLink[], personId: number) =>
  links.filter((l) => l.personId === personId).map((l) => l.patronId);

